      "location_ids": [
        "loc_glassgate_locks"
      ]
    },
    {
      "id": "fac_glassblower_guild",
      "name": "The Glassblower Guild",
      "description": "Artisans who fire their kilns on lagoon gas and hold the charter for every bell and window.",
      "location_ids": [
        "loc_bellmakers_quay"
      ]
    },
    {
      "id": "fac_ferry_cooperative",
      "name": "The Ferry Cooperative",
      "description": "Sail and paddle barge crews who haul harvest, glass and dredged silt across the lagoon.",
      "location_ids": [
        "loc_algae_fields"
      ]
    }
  ],
  "rules": [
    {
      "id": "rul_tide_power",
      "statement": "All power in the city comes from the tide, the sun or the algae digesters; combustion engines are banned by charter.",
      "category": "technology"
    },
    {
      "id": "rul_lock_oath",
      "statement": "Every gate crew must clear its lock before each spring tide, whatever the guild calendar says.",
      "category": "social"
    },
    {
      "id": "rul_bell_code",
      "statement": "A channel bell cast out of tune must be recast within a day, because the whole lagoon navigates by its ring.",
